// Writes robot-templates.ts: the files a robot's workspace needs (the helper, the build script, two examples), copied from 04-walks-home/body/ as strings, so the build_robot tool can put them in any computer (the tab's, a VM's)
// with no file access to this repository. A test holds the generated file equal to what this prints.
//   node scripts/gen-robot-templates.mjs [--check]
import { readFileSync, writeFileSync } from "node:fs";

const here = new URL(".", import.meta.url);
const body = (f) => readFileSync(new URL(`../../04-walks-home/body/${f}`, here), "utf8");
/** What the examples import, seen from robot/examples/. */
const example = (f) => body(f).replace('from "./lib.mjs"', 'from "../lib.mjs"');
const files = { "lib.mjs": body("lib.mjs"), "build.mjs": body("build.mjs"), "examples/dog.mjs": example("dog.example.mjs"), "examples/dino.mjs": example("dino.example.mjs") };
export const generated = `// GENERATED by scripts/gen-robot-templates.mjs from 04-walks-home/body/*.mjs: do not edit; a test holds it equal. The files robot/ needs, as strings.
export const ROBOT_TEMPLATES: Readonly<Record<string, string>> = ${JSON.stringify(files, null, 1)};
`;
if (process.argv[2] === "--check") {
  const have = readFileSync(new URL("../robot-templates.ts", here), "utf8");
  if (have !== generated) { console.error("robot-templates.ts is out of date: run node scripts/gen-robot-templates.mjs"); process.exit(1); }
} else if (import.meta.url === `file://${process.argv[1]}`) {
  writeFileSync(new URL("../robot-templates.ts", here), generated);
  console.log("wrote robot-templates.ts");
}
